#[tokio::test]
async fn structured_custom_pin_refuses_named_provider_migration_but_accepts_literal_custom() {
    let pin = || {
        Some(
            toml::from_str::<crate::config::SubagentsConfig>(
                "[roles.reviewer]\nmodel = 'custom/model-x'\n",
            )
            .unwrap(),
        )
    };
    let named = crate::config::Config {
        provider: Some("TeamA".into()),
        providers: Some(crate::config::ProvidersConfig {
            custom: HashMap::from([(
                "TeamA".into(),
                crate::config::ProviderConfig {
                    kind: Some("openai-compatible".into()),
                    base_url: Some("http://127.0.0.1:1/v1".into()),
                    api_key: Some("fixture-named-key".into()),
                    model: Some("model-x".into()),
                    ..Default::default()
                },
            )]),
            ..Default::default()
        }),
        subagents: pin(),
        ..Default::default()
    };
    assert_eq!(
        named
            .resolve_provider_identity("custom")
            .unwrap()
            .key
            .as_str(),
        "TeamA",
        "historical session migration remains available and is the exact rejected pin shape"
    );
    let literal = crate::config::Config {
        provider: Some("custom".into()),
        default_text_model: Some("model-x".into()),
        subagents: pin(),
        ..Default::default()
    }
    .with_legacy_root(
        Some("fixture-literal-key".into()),
        Some("http://127.0.0.1:2/v1".into()),
    );
    for (config, should_bind) in [(named, false), (literal, true)] {
        let mut runtime = stub_runtime();
        runtime.client = CodewhaleClient::new(&config).unwrap();
        runtime.api_config = Some(Arc::new(config));
        runtime.model = "parent-model".into();
        let endpoint = runtime.client.base_url().to_string();
        let request = parse_spawn_request(&json!({
            "prompt":"review", "type":"reviewer", "model":"custom/model-x"
        }))
        .unwrap();
        let result = bind_spawn_model_route(&mut runtime, &request, None, true, true).await;
        if should_bind {
            assert_eq!(result.unwrap().1, SpawnRouteSource::RolePin);
            assert_eq!(runtime.model, "model-x");
            assert_eq!(
                runtime
                    .api_config
                    .as_ref()
                    .unwrap()
                    .active_provider_identity()
                    .unwrap()
                    .key
                    .as_str(),
                "custom"
            );
        } else {
            let error =
                result.expect_err("an authored custom pin cannot migrate to sole named TeamA");
            assert!(error.to_string().contains("not a wildcard"), "{error}");
            assert_eq!(
                runtime.model, "parent-model",
                "refusal must not install a child route"
            );
        }
        assert_eq!(runtime.client.base_url(), endpoint);
    }
}

#[test]
fn saved_role_ambiguity_fails_unless_a_higher_priority_pin_selects_the_route() {
    let root = tempdir().unwrap();
    for id in ["review-a", "review-b"] {
        std::fs::write(root.path().join(format!("{id}.toml")), format!(
            "id = '{id}'\nbase_role = 'reviewer'\nprovider = 'deepseek'\nmodel = 'deepseek-v4-flash'\n",
        )).unwrap();
    }
    let profiles = crate::fleet::profile::load_agent_profiles_from_dir(root.path()).unwrap();
    assert_eq!(profiles.len(), 2);
    let roster = FleetRoster::from_members(profiles);
    let mut runtime = stub_runtime();
    let mut request = parse_spawn_request(&json!({"prompt":"review", "type":"reviewer"})).unwrap();
    let error = resolve_spawn_route_profile(&runtime, &mut request, &roster)
        .expect_err("an implicit role must not choose arbitrarily between saved pins");
    assert!(error.to_string().contains("ambiguous"), "{error}");
    assert_eq!(
        request.profile, None,
        "failed selection must not stamp a member"
    );

    Arc::make_mut(runtime.api_config.as_mut().unwrap()).subagents = Some(
        toml::from_str::<crate::config::SubagentsConfig>(
            "[roles.reviewer]\nmodel = 'deepseek-v4-pro'\n",
        )
        .unwrap(),
    );
    assert!(
        resolve_spawn_route_profile(&runtime, &mut request, &roster)
            .unwrap()
            .is_none(),
        "a manual pin precedes implicit saved-role selection"
    );
    assert_eq!(
        resolve_spawn_model_selection(&runtime, &request)
            .unwrap()
            .source,
        SpawnRouteSource::RolePin
    );

    let mut explicit =
        parse_spawn_request(&json!({"prompt":"review", "profile":"review-b"})).unwrap();
    let selected = resolve_spawn_route_profile(&runtime, &mut explicit, &roster)
        .unwrap()
        .expect("an explicit saved identity precedes the manual pin");
    assert_eq!(selected.id, "review-b");
    assert_eq!(selected.profile.model.as_deref(), Some("deepseek-v4-flash"));
    assert_eq!(explicit.agent_type, FleetRole::Reviewer);
}

/// A prompt-only spawn must not be refused over a role the caller never wrote.
///
/// `request.agent_type` defaults to `FleetRole::Worker`, whose `as_str()` is
/// `"general"`, so the route lookup synthesized `role:general` for a call that
/// named no type, role or profile. Two saved members sharing role `general` then
/// made every bare `agent(action=start, ...)` fail at the tool boundary (#6244).
/// The refusal is still correct when the caller *did* ask — that half is pinned
/// by `saved_role_ambiguity_fails_unless_a_higher_priority_pin_selects_the_route`.
#[test]
fn prompt_only_spawn_survives_an_ambiguous_default_role() {
    let root = tempdir().unwrap();
    for id in ["general-a", "general-b"] {
        std::fs::write(
            root.path().join(format!("{id}.toml")),
            format!(
                "id = '{id}'\nbase_role = 'general'\nprovider = 'deepseek'\nmodel = 'deepseek-v4-flash'\n",
            ),
        )
        .unwrap();
    }
    let profiles = crate::fleet::profile::load_agent_profiles_from_dir(root.path()).unwrap();
    assert_eq!(profiles.len(), 2);
    let roster = FleetRoster::from_members(profiles);
    let runtime = stub_runtime();

    let mut request = parse_spawn_request(&json!({"prompt":"do the thing"})).unwrap();
    assert!(
        !request.agent_type_explicit,
        "a prompt-only spawn must not report an explicit type"
    );
    assert_eq!(request.assignment.role, None);

    let member = resolve_spawn_route_profile(&runtime, &mut request, &roster)
        .expect("an ambiguous default role must not block a prompt-only spawn");
    assert!(
        member.is_none(),
        "no member is pinned, so the spawn falls through to the session route"
    );
    assert_eq!(
        request.profile, None,
        "an unusable pin must not stamp a member"
    );

    // The same roster still refuses when the caller actually named the role.
    let mut asked = parse_spawn_request(&json!({"prompt":"do the thing", "type":"general"}))
        .expect("an explicit general type parses");
    if asked.agent_type_explicit {
        let error = resolve_spawn_route_profile(&runtime, &mut asked, &roster)
            .expect_err("an explicitly requested ambiguous role must still refuse");
        let message = error.to_string();
        assert!(message.contains("ambiguous"), "{message}");
        assert!(
            message.contains("profile"),
            "the refusal must say how to choose one: {message}"
        );
    }
}

#[test]
fn providerless_spawn_model_gate_rejects_known_foreign_route_before_spawn() {
    let runtime = stub_runtime_for_provider("moonshot");
    let mut selection = SpawnModelSelection {
        model_route: ModelRoute::Fixed("deepseek-v4-pro".to_string()),
        source: SpawnRouteSource::TaskModel,
    };

    let err = resolve_fixed_spawn_model_route(&runtime, &mut selection, true)
        .expect_err("Moonshot must not receive a provider-less DeepSeek model pin");
    let message = err.to_string();
    assert!(
        message.contains("deepseek-v4-pro"),
        "names model: {message}"
    );
    assert!(
        message.contains("moonshot"),
        "names resolved route: {message}"
    );
    assert!(
        message.contains("deepseek"),
        "names catalog owner: {message}"
    );

    let mut unknown = SpawnModelSelection {
        model_route: ModelRoute::Fixed("private-finetune-v7".to_string()),
        source: SpawnRouteSource::TaskModel,
    };
    resolve_fixed_spawn_model_route(&runtime, &mut unknown, true)
        .expect("unknown custom model ids remain provider-authoritative");

    let mut inherited = SpawnModelSelection {
        model_route: ModelRoute::Inherit,
        source: SpawnRouteSource::RunModel,
    };
    resolve_fixed_spawn_model_route(&runtime, &mut inherited, true)
        .expect("session-inherited routes are unchanged");

    let openrouter = stub_runtime_for_provider("openrouter");
    let mut explicit = SpawnModelSelection {
        model_route: ModelRoute::Fixed("deepseek-v4-pro".to_string()),
        source: SpawnRouteSource::RoleDefault,
    };
    resolve_fixed_spawn_model_route(&openrouter, &mut explicit, false)
        .expect("an explicit aggregator route remains allowed");
    assert_eq!(
        explicit.model_route,
        ModelRoute::Fixed(crate::config::DEFAULT_OPENROUTER_MODEL.to_string()),
        "the child and receipt must use the provider's exact wire id"
    );
}

#[test]
fn providerless_foreign_spawn_default_inherits_session_route() {
    // #5099 / checklist §2.2: a moonshot parent spawning a default child whose
    // role default is a provider-less deepseek id must inherit the session
    // route instead of hard-failing the spawn on a model the session never
    // chose.
    let runtime = stub_runtime_for_provider("moonshot");
    let mut selection = SpawnModelSelection {
        model_route: ModelRoute::Fixed("deepseek-v4-flash".to_string()),
        source: SpawnRouteSource::RoleDefault,
    };
    resolve_fixed_spawn_model_route(&runtime, &mut selection, true)
        .expect("provider-less foreign default must not fail the spawn");
    assert_eq!(
        selection.model_route,
        ModelRoute::Inherit,
        "role default downgrades to the session route"
    );
    assert_eq!(
        selection.source,
        SpawnRouteSource::RunModel,
        "receipt provenance reflects the inherit"
    );

    // An explicit caller `task.model` pin keeps the pin-vs-inherit error; the
    // guard is only bypassed for defaults the session did not choose.
    let mut explicit = SpawnModelSelection {
        model_route: ModelRoute::Fixed("deepseek-v4-flash".to_string()),
        source: SpawnRouteSource::TaskModel,
    };
    let err = resolve_fixed_spawn_model_route(&runtime, &mut explicit, true)
        .expect_err("explicit task.model keeps the known-foreign guard");
    let message = err.to_string();
    assert!(
        message.contains("inherit the session route"),
        "error names the exact fix: {message}"
    );

    // A same-provider default still resolves to the exact wire id.
    let deepseek = stub_runtime();
    let mut owned = SpawnModelSelection {
        model_route: ModelRoute::Fixed("deepseek-v4-flash".to_string()),
        source: SpawnRouteSource::RoleDefault,
    };
    resolve_fixed_spawn_model_route(&deepseek, &mut owned, true)
        .expect("same-provider default resolves normally");
    assert!(
        matches!(owned.model_route, ModelRoute::Fixed(_)),
        "owned default stays fixed: {:?}",
        owned.model_route
    );
}

#[test]
fn spawn_route_sources_refresh_removes_stale_pins_and_overlays_live_config() {
    // Disk/current config own saved route defaults; removed launch-time pins
    // cannot survive refresh. Explicit live subagent settings still win.
    let mut runtime = stub_runtime();
    runtime
        .role_models
        .insert("builder".to_string(), "stale-launch-model".into());

    refresh_spawn_route_sources(&mut runtime);
    assert_eq!(
        runtime
            .role_models
            .get("builder")
            .map(|pin| pin.model.as_str()),
        None,
        "removed launch-time defaults cannot survive refresh"
    );

    let config = runtime.api_config.clone().expect("stub config");
    let mut live = (*config).clone();
    live.subagents = Some(crate::config::SubagentsConfig {
        worker_model: Some("live-config-model".to_string()),
        ..Default::default()
    });
    runtime.api_config = Some(std::sync::Arc::new(live));

    refresh_spawn_route_sources(&mut runtime);
    assert_eq!(
        runtime
            .role_models
            .get("builder")
            .map(|pin| pin.model.as_str()),
        None,
        "removed pins remain absent when other defaults change"
    );
    assert_eq!(
        runtime
            .role_models
            .get("worker")
            .map(|pin| pin.model.as_str()),
        Some("live-config-model"),
        "live config wins on top of the snapshot"
    );
    assert_eq!(
        runtime
            .role_models
            .get("general")
            .map(|pin| pin.model.as_str()),
        Some("live-config-model"),
        "worker override covers the general alias too"
    );
}

#[test]
fn test_child_max_spawn_depth_request_only_narrows() {
    // No request: inherit unchanged.
    assert_eq!(child_max_spawn_depth_for_spawn(5, 2, None), 5);
    // Explicit request alone still cannot widen past the inherited budget (#5253).
    assert_eq!(child_max_spawn_depth_for_spawn(2, 0, Some(3)), 2);
    assert_eq!(
        child_max_spawn_depth_for_spawn(2, 0, Some(codewhale_config::MAX_SPAWN_DEPTH_CEILING)),
        2
    );
    // A request below the inherited budget is still honored (clamp, don't force).
    assert_eq!(child_max_spawn_depth_for_spawn(5, 0, Some(3)), 3);
}

/// A descendant subagent must not widen the absolute recursion budget its root
/// session selected by supplying an explicit `max_depth` on a nested spawn
/// (#5253). The inherited budget is a hard cap even when the request (clamped
/// to the global ceiling) is larger.
#[test]
fn test_child_max_spawn_depth_request_cannot_widen_inherited_budget() {
    // Root chose an absolute max_spawn_depth of 2; a nested child at
    // spawn_depth 2 requesting the global ceiling must stay bounded by 2,
    // not jump to the ceiling. Before the fix this returned
    // MAX_SPAWN_DEPTH_CEILING (8), letting the descendant keep spawning past
    // the root's chosen boundary.
    assert_eq!(
        child_max_spawn_depth_for_spawn(2, 2, Some(codewhale_config::MAX_SPAWN_DEPTH_CEILING)),
        2
    );
    // A request below the inherited budget is still honored (clamp, don't force).
    assert_eq!(child_max_spawn_depth_for_spawn(5, 0, Some(3)), 3);
}

/// An explicit spawn-time thinking tier reaches the request unchanged: roles
/// carry no reasoning tier of their own, so there is nothing to outrank or
/// inherit — the caller's tier is the tier.
#[test]
fn test_explicit_spawn_thinking_reaches_the_request() {
    let mut request = parse_spawn_request(&json!({
        "prompt": "review this",
        "profile": "reviewer",
        "thinking": "off"
    }))
    .expect("parse");
    resolve_spawn_role(&mut request).expect("resolve");
    assert_eq!(
        request.thinking,
        SubAgentThinking::Effort(ReasoningEffort::Off)
    );

    // And it actually lands on the resolved route.
    let route = fallback_subagent_assignment_route(
        &stub_runtime(),
        None,
        ModelRoute::Inherit,
        request.thinking,
    );
    assert_eq!(route.reasoning_effort.as_deref(), Some("off"));
}

#[test]
fn test_unset_spawn_thinking_inherits_the_session_tier() {
    let mut request = parse_spawn_request(&json!({"prompt": "look around", "profile": "explore"}))
        .expect("parse");
    resolve_spawn_role(&mut request).expect("resolve");
    assert_eq!(request.thinking, SubAgentThinking::Inherit);
}

/// Roles bind no route (#5046 inverted): the dispatching model may always set
/// `model` or `model_strength` — every role accepts model routing options.
#[test]
fn role_dispatch_allows_model_and_model_strength_options() {
    // Named role (explore) + explicit model → allowed.
    let mut request = parse_spawn_request(&json!({
        "prompt": "scan for callers",
        "profile": "explore",
        "model": "deepseek-v4-flash"
    }))
    .expect("parse should succeed");
    resolve_spawn_role(&mut request).expect("model on a role must be allowed");
    assert_eq!(request.agent_type, FleetRole::Scout);
    assert_eq!(request.model.as_deref(), Some("deepseek-v4-flash"));

    // Named role (implement) + explicit model_strength → allowed.
    let mut request = parse_spawn_request(&json!({
        "prompt": "apply the fix",
        "profile": "implement",
        "model_strength": "faster",
        "write_roots": ["."]
    }))
    .expect("parse should succeed");
    resolve_spawn_role(&mut request).expect("model_strength on a role must be allowed");
    assert_eq!(request.agent_type, FleetRole::Builder);
    assert!(request.model_strength_explicit);

    // Explicit profile=general with model → allowed.
    let mut request = parse_spawn_request(&json!({
        "prompt": "do work",
        "profile": "general",
        "model": "deepseek-v4-flash",
        "write_roots": ["."]
    }))
    .expect("parse should succeed");
    resolve_spawn_role(&mut request).expect("model on 'general' must be allowed");
    assert_eq!(request.model.as_deref(), Some("deepseek-v4-flash"));

    // No profile at all (default general) with model_strength → model and
    // strength are allowed at parse time; resolve_spawn_role is a no-op.
    let request = parse_spawn_request(&json!({
        "prompt": "do some work",
        "model_strength": "faster",
        "write_roots": ["."]
    }))
    .expect("unprofiled spawn with model_strength should parse");
    assert!(request.profile.is_none());
    assert!(request.model_strength_explicit);
    assert_eq!(request.model_strength, SubAgentModelStrength::Faster);
}

