#[test]
fn test_parse_spawn_request_rejects_human_model_name_as_role() {
    // A model name is not a role: without a roster of saved members there is
    // nothing for it to resolve to, so it fails closed with the role list.
    let input = json!({
        "prompt": "do work",
        "role": "DeepSeek V4 Flash"
    });
    let mut parsed = parse_spawn_request(&input).expect("human role selector should parse");
    assert_eq!(parsed.profile.as_deref(), Some("DeepSeek V4 Flash"));
    assert_eq!(parsed.assignment.role.as_deref(), Some("DeepSeek V4 Flash"));

    let err = resolve_spawn_role(&mut parsed).expect_err("a model name must not resolve as a role");
    assert!(
        err.to_string()
            .contains("Unknown Fleet role/profile 'DeepSeek V4 Flash'"),
        "{err}"
    );
}

#[test]
fn test_parse_spawn_request_accepts_fleet_role_token_for_runtime_resolution() {
    let input = json!({
        "prompt": "do work",
        "role": "release_lead"
    });
    let parsed = parse_spawn_request(&input).expect("fleet role token should parse");
    assert_eq!(parsed.agent_type, FleetRole::Worker);
    assert!(!parsed.agent_type_explicit);
    assert_eq!(parsed.assignment.role.as_deref(), Some("release_lead"));
    assert_eq!(parsed.profile.as_deref(), Some("release_lead"));

    // A saved-member id is not a role: it fails closed with the role list.
    let mut parsed = parsed;
    let err = resolve_spawn_role(&mut parsed).expect_err("release_lead must not resolve");
    assert!(
        err.to_string()
            .contains("Unknown Fleet role/profile 'release_lead'"),
        "{err}"
    );

    let mut scout = parse_spawn_request(&json!({"prompt": "map it", "role": "scout"}))
        .expect("canonical scout role");
    resolve_spawn_role(&mut scout).expect("scout should resolve");
    assert_eq!(scout.agent_type, FleetRole::Scout);
}

#[test]
fn test_parse_spawn_request_accepts_full_role_vocabulary() {
    // Regression for #2649: every token `FleetRole::from_str` accepts must
    // pass the spawn boundary through `role` *and* `type`, in any case and
    // with surrounding whitespace, land on the canonical serialized role,
    // never become a profile key, and conflict with a different type.
    for (role, expected_type, expected_role) in [
        ("general", FleetRole::Worker, "general"),
        ("general-purpose", FleetRole::Worker, "general"),
        ("general_purpose", FleetRole::Worker, "general"),
        ("worker", FleetRole::Worker, "general"),
        ("default", FleetRole::Worker, "general"),
        ("scout", FleetRole::Scout, "explore"),
        ("explore", FleetRole::Scout, "explore"),
        ("exploration", FleetRole::Scout, "explore"),
        ("explorer", FleetRole::Scout, "explore"),
        ("plan", FleetRole::Planner, "planner"),
        ("planning", FleetRole::Planner, "planner"),
        ("planner", FleetRole::Planner, "planner"),
        ("awaiter", FleetRole::Planner, "planner"),
        ("review", FleetRole::Reviewer, "reviewer"),
        ("code-review", FleetRole::Reviewer, "reviewer"),
        ("code_review", FleetRole::Reviewer, "reviewer"),
        ("reviewer", FleetRole::Reviewer, "reviewer"),
        ("implementer", FleetRole::Builder, "implement"),
        ("implement", FleetRole::Builder, "implement"),
        ("implementation", FleetRole::Builder, "implement"),
        ("builder", FleetRole::Builder, "implement"),
        ("test", FleetRole::Verifier, "test"),
        ("verifier", FleetRole::Verifier, "test"),
        ("verify", FleetRole::Verifier, "test"),
        ("verification", FleetRole::Verifier, "test"),
        ("validator", FleetRole::Verifier, "test"),
        ("tester", FleetRole::Verifier, "test"),
        ("consultant", FleetRole::Consultant, "advisor"),
        ("oracle", FleetRole::Consultant, "advisor"),
        ("advisor", FleetRole::Consultant, "advisor"),
        ("custom", FleetRole::Custom, "custom"),
    ] {
        let shouted = format!("  {} ", role.to_ascii_uppercase());
        for (key, spelling) in [
            ("role", role.to_string()),
            ("role", shouted.clone()),
            ("type", role.to_string()),
            ("type", shouted),
        ] {
            let mut input = json!({ "prompt": "do work", key: spelling });
            if matches!(&expected_type, FleetRole::Worker | FleetRole::Builder) {
                input["write_roots"] = json!(["."]);
            } else if expected_type == FleetRole::Custom {
                input["write_authority"] = json!("workspace_write");
                input["write_roots"] = json!(["."]);
            }
            let mut parsed = parse_spawn_request(&input)
                .unwrap_or_else(|e| panic!("{key}={spelling:?} should parse, got {e}"));
            assert_eq!(
                parsed.agent_type, expected_type,
                "type for {key}={spelling:?}"
            );
            assert_eq!(
                parsed.assignment.role.as_deref(),
                Some(expected_role),
                "canonical role for {key}={spelling:?}"
            );
            assert_eq!(
                serde_json::to_string(&parsed.agent_type).expect("serialize role"),
                format!("\"{expected_role}\""),
                "serialized role for {key}={spelling:?} must be canonical"
            );
            assert!(
                parsed.profile.is_none(),
                "descriptive alias {key}={spelling:?} must not become a role profile"
            );
            resolve_spawn_role(&mut parsed).unwrap_or_else(|e| {
                panic!("{key}={spelling:?} should resolve without a profile: {e}")
            });
        }

        // The same alias paired with a different explicit type is a conflict,
        // not a silent pick of either side.
        let other = if expected_type == FleetRole::Scout {
            "general"
        } else {
            "explore"
        };
        let err = parse_spawn_request(&json!({
            "prompt": "do work",
            "type": other,
            "role": role,
        }))
        .expect_err("conflicting type and role alias must fail");
        assert!(
            err.to_string()
                .contains("Fleet role conflicts with the explicit legacy agent type"),
            "conflict error for role {role:?} with type {other:?}: {err}"
        );
    }
}

#[test]
fn test_invalid_role_error_lists_real_aliases() {
    // Well-formed fleet role tokens parse and then fail clearly at role
    // resolution time with the closed role set (#4177).
    let input = json!({
        "prompt": "do work",
        "role": "nonsense",
        "write_roots": ["."]
    });
    let mut request = parse_spawn_request(&input).expect("fleet role token should parse");
    let err = resolve_spawn_role(&mut request)
        .expect_err("unknown fleet role should fail at runtime resolution")
        .to_string();
    assert!(
        err.contains("Unknown Fleet role/profile 'nonsense'"),
        "{err}"
    );
    assert!(err.contains("explore"), "hint should list explore: {err}");
    assert!(err.contains("reviewer"), "hint should list reviewer: {err}");
    assert!(err.contains("test"), "hint should list test: {err}");
    assert!(err.contains("custom"), "hint should list custom: {err}");
    assert!(err.contains("general"), "hint should list general: {err}");
    assert!(
        err.contains("legacy aliases remain accepted"),
        "hint should explain compatibility aliases: {err}"
    );
}

#[test]
fn plugin_agent_profile_resolves_from_staged_snapshot_and_rechecks_revocation() {
    let _lock = crate::test_support::lock_test_env();
    let fixture = crate::plugins::test_fixture::DeclarativePluginFixture::new();
    let config = codewhale_config::FleetConfigToml::default();
    let roster = FleetRoster::load_with_plugins(&config, &fixture.workspace, &fixture.registry);
    let member = roster.get("plugin-scout").expect("plugin Agent is loaded");
    assert_eq!(member.origin, crate::fleet::roster::ProfileOrigin::Plugin);
    assert!(member.plugin_authority.is_some());
    assert!(
        member.source.starts_with(
            fixture
                .registry
                .get("runtime-demo")
                .and_then(|plugin| plugin.staged_root.as_deref())
                .expect("staged root")
        ),
        "Agent profile must execute from the immutable staged snapshot"
    );

    // Direct agent dispatch uses the same staged identity and current
    // component authority as durable Fleet.
    let mut request = parse_spawn_request(&json!({
        "prompt": "inspect the plugin boundary",
        "profile": "plugin-scout"
    }))
    .expect("spawn request parses");
    let resolved = resolve_spawn_profile(&mut request, &roster)
        .expect("trusted plugin Agent resolves")
        .expect("saved identity");
    assert_eq!(resolved.id, "plugin-scout");
    assert_eq!(request.agent_type, FleetRole::Scout);

    let inactive = fixture.disable_from_fresh_registry();
    let mut request =
        parse_spawn_request(&json!({"prompt":"Inspect.", "profile":"plugin-scout"})).unwrap();
    let denied = resolve_spawn_profile(&mut request, &roster)
        .expect_err("cached roster cannot retain revoked authority");
    assert!(denied.to_string().contains("unavailable"), "{denied}");
    let reloaded = FleetRoster::load_with_plugins(&config, &fixture.workspace, &inactive);
    assert!(
        reloaded.get("plugin-scout").is_none(),
        "reload removes the disabled plugin Agent"
    );
}

fn schema_property_description<'a>(schema: &'a Value, property: &str) -> &'a str {
    schema["properties"][property]["description"]
        .as_str()
        .unwrap_or_else(|| panic!("missing description for schema property {property:?}"))
}

fn draft_2020_validator(schema: &Value) -> jsonschema::Validator {
    jsonschema::options()
        .with_draft(jsonschema::Draft::Draft202012)
        .build(schema)
        .expect("valid Draft 2020-12 tool schema")
}

#[test]
fn subagent_tool_schemas_advertise_real_type_and_role_vocabulary() {
    let tmp = tempdir().expect("tempdir");
    let manager = new_shared_subagent_manager(tmp.path().to_path_buf(), 1);
    let agent_schema = AgentTool::new(manager, stub_runtime()).input_schema();

    let description = schema_property_description(&agent_schema, "type");
    for alias in [
        "general",
        "explore",
        "planner",
        "reviewer",
        "implement",
        "test",
        "advisor",
        "custom",
    ] {
        assert!(
            description.contains(alias),
            "type description should list accepted type {alias:?}: {description}"
        );
    }
    assert!(agent_schema["properties"].get("role").is_none());
    // Route controls must be discoverable alongside lifecycle and scope.
    let mut advertised: Vec<&str> = agent_schema["properties"]
        .as_object()
        .expect("agent schema properties must be an object")
        .keys()
        .map(String::as_str)
        .collect();
    advertised.sort_unstable();
    let mut expected = [
        "action",
        "agent_id",
        "agent_ids",
        "all_parked",
        "allowed_tools",
        "coordination_contracts",
        "cwd",
        "deliverables",
        "detail",
        "detached",
        "exact_files",
        "expected_artifact",
        "fork_context",
        "limit",
        "max_output_tokens",
        "max_steps",
        "message",
        "model",
        "model_strength",
        "name",
        "offset",
        "profile",
        "prompt",
        "resume_from",
        "thinking",
        "type",
        "until",
        "wall_time_secs",
        "worktree",
        "write_authority",
        "write_roots",
    ];
    expected.sort_unstable();
    assert_eq!(
        advertised, expected,
        "the agent tool must advertise lifecycle, scope and routing controls: {}",
        agent_schema["properties"]
    );
    for unadvertised in [
        "max_depth",
        "workspace_policy",
        "worktree_base",
        "worktree_branch",
        "worktree_path",
        // "cwd" deliberately advertised since #6314: the multi-checkout
        // refusal names it as the remedy, so the schema must teach it.
        "deliberate",
        "dependencies",
        "acceptance",
        "timeout_secs",
        "reason",
        "include_archived",
        // Pre-#5324 precedent: parse-accepted but never advertised.
    ] {
        assert!(
            agent_schema["properties"].get(unadvertised).is_none(),
            "agent schema must not advertise {unadvertised:?}: {}",
            agent_schema["properties"]
        );
    }
    let worktree = schema_property_description(&agent_schema, "worktree");
    assert!(
        worktree.contains("git worktree") && worktree.contains("parallel edit"),
        "worktree description should teach isolated parallel edits: {worktree}"
    );
}

#[test]
fn agent_start_schema_documents_hidden_spawn_requirements() {
    // #6194 item 6: every spawn-time refusal must be discoverable before the
    // call — the parent burned dispatches learning these from errors.
    let tmp = tempdir().expect("tempdir");
    let manager = new_shared_subagent_manager(tmp.path().to_path_buf(), 1);
    let schema = AgentTool::new(manager, stub_runtime()).input_schema();
    let allowed = schema_property_description(&schema, "allowed_tools");
    for needle in ["type=custom", "non-empty", "narrows"] {
        assert!(
            allowed.contains(needle),
            "allowed_tools description should teach {needle:?}: {allowed}"
        );
    }
    let profile = schema_property_description(&schema, "profile");
    for needle in ["ambiguous", "action=roster"] {
        assert!(
            profile.contains(needle),
            "profile description should teach {needle:?}: {profile}"
        );
    }
    let authority = schema_property_description(&schema, "write_authority");
    for needle in ["type=custom", "workspace_write"] {
        assert!(
            authority.contains(needle),
            "write_authority description should teach {needle:?}: {authority}"
        );
    }
    let model = schema_property_description(&schema, "model");
    assert!(
        model.contains("resolved route"),
        "model description should point at per-role resolved routes: {model}"
    );
    // #6314: the multi-checkout refusal tells the caller to specify cwd,
    // so the schema must advertise it before the first failure.
    let cwd = schema_property_description(&schema, "cwd");
    for needle in ["worktree", "several checkouts"] {
        assert!(
            cwd.contains(needle),
            "cwd description should teach {needle:?}: {cwd}"
        );
    }
}

#[test]
fn spawn_limits_accept_whole_number_floats_and_still_refuse_fractions() {
    // Providers that serialize every number as a float send `900.0`.
    let request = parse_spawn_request(&json!({
        "prompt": "p",
        "max_steps": 300.0,
        "wall_time_secs": 900.0,
        "max_output_tokens": 4096.0,
    }))
    .expect("whole-number floats are integers");
    assert_eq!(request.max_steps, Some(300));
    assert_eq!(request.wall_time, Some(Duration::from_secs(900)));
    assert_eq!(request.max_output_tokens, Some(4096));

    for bad in [json!(2.5), json!(0.0), json!(-1.0), json!("900")] {
        let error = parse_spawn_request(&json!({"prompt": "p", "wall_time_secs": bad}))
            .expect_err("fractional, zero, negative and string limits stay refused")
            .to_string();
        assert!(
            error.contains("wall_time_secs must be between 1 and"),
            "{error}"
        );
    }
}

// The wait surfaces block the turn, so the model-facing text must disclose
// the bounded block (default 30s, max 120s) and the timed_out receipt shape;
// an undisclosed finite block reads as a hang when nothing settles.
#[test]
fn wait_schema_text_discloses_timeout_bound_and_timed_out_receipt() {
    let tmp = tempdir().expect("tempdir");
    let manager = new_shared_subagent_manager(tmp.path().to_path_buf(), 1);
    let agent_schema = AgentTool::new(manager.clone(), stub_runtime()).input_schema();
    let until = schema_property_description(&agent_schema, "until");
    // The advertised numbers are tied to the runtime constants so a drift in
    // either direction (constant change, copy change) turns the other red.
    assert!(
        until.contains(&format!(
            "default {}s, max {}s",
            SUBAGENT_WAIT_DEFAULT_TIMEOUT_SECS, SUBAGENT_WAIT_MAX_TIMEOUT_SECS
        )) && until.contains("timed_out"),
        "agent(action=wait) until description must disclose the runtime \
         timeout bound and the timed_out receipt:\n{until}"
    );

    let wait_tool = AgentsWaitTool::new(manager);
    let wait_description = wait_tool.description();
    assert!(
        wait_description.contains(&format!(
            "timeout_secs (default {}, max {})",
            coord::COORD_WAIT_DEFAULT_TIMEOUT_SECS,
            coord::COORD_WAIT_MAX_TIMEOUT_SECS
        )) && wait_description.contains("timed_out=true"),
        "agents/wait description must disclose the runtime timeout bound and \
         the timed_out receipt:\n{wait_description}"
    );
}

// The two wait faces advertise from two independent constant sets, so each
// face's own pin can stay green while the surfaces drift numerically apart;
// this cross-assertion closes that gap.
#[test]
fn wait_bound_constants_agree_across_both_wait_faces() {
    assert_eq!(
        SUBAGENT_WAIT_DEFAULT_TIMEOUT_SECS,
        coord::COORD_WAIT_DEFAULT_TIMEOUT_SECS,
        "the agent broadcast face and the agents/wait face must advertise the \
         same default timeout"
    );
    assert_eq!(
        SUBAGENT_WAIT_MAX_TIMEOUT_SECS,
        coord::COORD_WAIT_MAX_TIMEOUT_SECS,
        "the agent broadcast face and the agents/wait face must advertise the \
         same maximum timeout"
    );
}

#[test]
fn agent_tool_unadvertised_fields_remain_parse_accepted() {
    // #5324 compat: the fields removed from the advertised schema must stay
    // parse-accepted and honored unchanged — saved transcripts, ACP/MCP
    // clients and Fleet configs still replay them, the same contract as the
    // retired `token_budget` key (docs/SUBAGENTS.md).
    let request = parse_spawn_request(&json!({
        "prompt": "summarize the diff",
        "model": "deepseek-v4-flash",
        "model_strength": "faster",
        "thinking": "max",
        "max_steps": 300,
        "wall_time_secs": 900,
        "max_depth": 2,
        "fork_context": false,
        "workspace_policy": "shared",
        "expected_artifact": "review findings",
        "dependencies": ["#5324"],
        "acceptance": ["tests pass"],
        "exact_files": ["Cargo.toml"],
        "coordination_contracts": ["public-api"],
        "deliberate": false,
    }))
    .expect("every removed field must stay parse-accepted");
    assert_eq!(request.model.as_deref(), Some("deepseek-v4-flash"));
    assert_eq!(request.model_strength, SubAgentModelStrength::Faster);
    assert!(request.model_strength_explicit);
    assert_eq!(subagent_thinking_label(request.thinking), "max");
    assert_eq!(request.max_steps, Some(300));
    assert_eq!(request.wall_time, Some(Duration::from_secs(900)));
    assert_eq!(request.max_depth, Some(2));
    assert_eq!(request.fork_context, Some(false));
    assert!(
        request.worktree.is_none(),
        "workspace_policy=shared must not fabricate a worktree"
    );
    assert_eq!(
        request.expected_artifact.as_deref(),
        Some("review findings")
    );
    assert_eq!(request.dependencies, vec!["#5324".to_string()]);
    assert_eq!(request.acceptance, vec!["tests pass".to_string()]);
    assert_eq!(request.exact_files, vec!["Cargo.toml".to_string()]);
    assert_eq!(
        request.coordination_contracts,
        vec!["public-api".to_string()]
    );

    // Declared authority still parses on its own (the containment rule that
    // read_only cannot also declare write scope is unchanged #5426/#5435
    // behavior, not schema rejection).
    let request = parse_spawn_request(&json!({
        "prompt": "p",
        "write_authority": "read_only",
    }))
    .expect("write_authority must stay parse-accepted");
    assert_eq!(request.write_authority, Some(SpawnWriteAuthority::ReadOnly));
    let err = parse_spawn_request(&json!({
        "prompt": "p",
        "write_authority": "read_only",
        "exact_files": ["Cargo.toml"],
    }))
    .expect_err("read_only plus a declared write scope stays refused");
    assert!(err.to_string().contains("read_only"), "{err}");

    // token_budget is retired from the runtime (#6189): runs are never
    // stopped by token accounting. Legacy input carrying it still parses;
    // the value is ignored, never enforced.
    parse_spawn_request(&json!({
        "prompt": "p",
        "token_budget": 5000,
    }))
    .expect("retired token_budget key stays parse-tolerated");

    // The removed lifecycle extras are still read on their actions:
    // action aliases keep parsing, wait still reads timeout_secs, status
    // still reads include_archived, and interrupt still reaches its target
    // resolution carrying reason (an unknown id proves parsing succeeded —
    // a schema-style rejection would name the field instead).
    assert_eq!(
        parse_agent_tool_action(&json!({"action": "wait", "timeout_secs": 5})).unwrap(),
        AgentToolAction::Wait
    );
    assert_eq!(
        parse_agent_tool_action(&json!({"op": "status", "include_archived": true})).unwrap(),
        AgentToolAction::Status
    );
    assert_eq!(
        parse_agent_tool_action(&json!({"action": "interrupt", "reason": "stale"})).unwrap(),
        AgentToolAction::Interrupt
    );
}

#[test]
fn agent_tool_role_schema_is_a_closed_canonical_enum() {
    let tmp = tempdir().expect("tempdir");
    let manager = new_shared_subagent_manager(tmp.path().to_path_buf(), 1);
    let agent_schema = AgentTool::new(manager, stub_runtime()).input_schema();

    // Exact canonical values, exact order. New models are told the closed
    // Fleet vocabulary and nothing else.
    let expected = json!([
        "general",
        "explore",
        "planner",
        "reviewer",
        "implement",
        "test",
        "advisor",
        "custom"
    ]);
    assert_eq!(
        agent_schema["properties"]["type"]["enum"], expected,
        "model-facing role schema must advertise exactly the canonical Fleet enum"
    );

    // The description teaches each canonical role; legacy aliases stay at
    // replay/deserialization boundaries.
    let description = schema_property_description(&agent_schema, "type");
    assert!(
        description.starts_with("Fleet role for this delegated worker."),
        "type description should lead with the Fleet role contract: {description}"
    );
    let lowered = description.to_ascii_lowercase();
    for canonical in [
        "general",
        "explore",
        "planner",
        "reviewer",
        "implement",
        "test",
        "advisor",
        "custom",
    ] {
        assert!(
            lowered.contains(canonical),
            "type description must advertise canonical vocabulary {canonical:?}: {description}"
        );
    }
}

#[test]
fn provider_schema_sanitizers_preserve_the_closed_fleet_role_enum() {
    use crate::tools::schema_sanitize;

    let tmp = tempdir().expect("tempdir");
    let manager = new_shared_subagent_manager(tmp.path().to_path_buf(), 1);
    let agent_schema = AgentTool::new(manager, stub_runtime()).input_schema();
    let expected = json!([
        "general",
        "explore",
        "planner",
        "reviewer",
        "implement",
        "test",
        "advisor",
        "custom"
    ]);

    // Generic Chat Completions sanitize pass.
    let mut plain = agent_schema.clone();
    schema_sanitize::sanitize(&mut plain);
    assert!(
        plain.get("dependentSchemas").is_some(),
        "generic chat schemas should retain action-dependent requirements"
    );
    assert_eq!(
        plain["dependentSchemas"]["action"]["anyOf"][0]["required"],
        json!(["prompt"]),
        "generic sanitization must not prune requirements that refer to root properties"
    );
    assert_eq!(
        plain["properties"]["type"]["enum"], expected,
        "chat completions sanitize must not erase or widen the role enum"
    );

    // Strict-mode structured outputs pass.
    let mut strict = agent_schema.clone();
    schema_sanitize::sanitize_for_strict(&mut strict);
    assert_eq!(
        strict["properties"]["type"]["enum"], expected,
        "strict-mode sanitize must not erase or widen the role enum"
    );

    // Anthropic Messages and OpenAI Responses (and xAI, an alias of the
    // Responses pass) share sanitize_for_responses; it strips root-level
    // enum keywords only and must keep this nested property enum intact.
    let mut responses = agent_schema.clone();
    let note = schema_sanitize::sanitize_for_responses(&mut responses);
    assert!(
        note.as_deref()
            .is_some_and(|note| note.contains("conditional requirements")),
        "dropping the action contract must be reported to the model"
    );
    assert_eq!(
        responses["properties"]["type"]["enum"], expected,
        "responses/anthropic sanitize must not erase or widen the role enum"
    );
    assert!(
        responses.get("dependentSchemas").is_none(),
        "responses/anthropic must drop their unsupported dependency keyword"
    );

    // Moonshot/Kimi must retain the supported field vocabulary while dropping
    // the one root dependency keyword MFJS cannot represent.
    let mut kimi = agent_schema.clone();
    schema_sanitize::sanitize_for_kimi_parameters(&mut kimi)
        .expect("agent schema must stay Kimi-compatible");
    assert_eq!(
        kimi["properties"]["type"]["enum"], expected,
        "kimi sanitize must not erase or widen the role enum"
    );
    assert!(
        kimi.get("dependentSchemas").is_none(),
        "Kimi MFJS must receive a schema without dependentSchemas"
    );
}

