const MCP_ACTION_TOOL: &str = "mcp_github_create_pull_request";

fn subagent_registry_with_mcp_action(auto_approve: bool) -> (ChildCoreProbe, tempfile::TempDir) {
    let home = tempdir().expect("private MCP probe receipt home");
    let mut runtime = stub_runtime();
    runtime.context = ToolContext::new(home.path());
    runtime = runtime.with_approval_receipt_store(Ok(
        crate::approval_log::ApprovalReceiptStore::new(home.path().join("sessions")),
    ));
    runtime.context.auto_approve = auto_approve;
    // Core dispatches MCP through the captured pool; the registry facade supplies its schema.
    runtime = runtime.with_mcp_pool(Some(Arc::new(tokio::sync::Mutex::new(
        crate::mcp::McpPool::new(crate::mcp::McpConfig::default()),
    ))));
    let mut registry = ChildCoreProbe::new(
        runtime,
        FleetRole::Worker,
        Some(vec![MCP_ACTION_TOOL.to_string()]),
        Arc::new(Mutex::new(TodoList::new())),
        Arc::new(Mutex::new(PlanState::default())),
    );
    registry
        .registry
        .register(crate::tools::registry::mcp_tool_adapter_for_test(
            MCP_ACTION_TOOL,
        ));
    (registry, home)
}

#[tokio::test]
async fn child_write_tool_fails_closed_outside_registered_scope() {
    let _env_lock = crate::test_support::lock_test_env();
    let home = tempdir().expect("isolated CODEWHALE_HOME");
    let _codewhale_home = crate::test_support::EnvVarGuard::set("CODEWHALE_HOME", home.path());
    let tmp = tempdir().expect("tempdir");
    std::fs::create_dir_all(tmp.path().join("src")).unwrap();
    std::fs::create_dir_all(tmp.path().join("outside")).unwrap();
    let manager = new_shared_subagent_manager(tmp.path().to_path_buf(), 2);
    {
        let mut guard = manager.write().await;
        assert_eq!(
            guard.insert_test_running_agent("scoped", tmp.path()),
            "agent_scoped"
        );
        guard
            .coordination
            .register_claim(
                WriteScopeClaim {
                    owner: "agent_scoped".into(),
                    roots: vec!["src".into()],
                    exact_files: vec![],
                    contracts: vec![],
                },
                false,
                |_| false,
            )
            .unwrap();
        guard
            .register_worker_with_coordination(make_write_worker_spec(
                "other-writer",
                tmp.path().to_path_buf(),
                "conflict",
            ))
            .expect("active conflicting writer");
    }
    let mut runtime = stub_runtime();
    runtime.manager = Arc::clone(&manager);
    runtime.context = ToolContext::new(tmp.path());
    runtime.context.auto_approve = true;
    runtime.worker_profile = WorkerRuntimeProfile::for_role(FleetRole::Builder);
    let registry = ChildCoreProbe::new_with_owner(
        runtime,
        FleetRole::Builder,
        "agent_scoped".into(),
        "implementer".into(),
        Some(vec![
            "File".into(),
            "Bash".into(),
            "Run".into(),
            "agents/coordinate".into(),
            "work_update".into(),
            "agent".into(),
        ]),
        Arc::new(Mutex::new(TodoList::new())),
        Arc::new(Mutex::new(PlanState::default())),
    );
    registry
        .execute(
            "agent_scoped",
            "File",
            json!({"action": "write", "path": "src/ok.txt", "content": "ok"}),
        )
        .await
        .expect("in-scope write");
    registry
        .execute(
            "agent_scoped",
            "agents/coordinate",
            json!({"action": "claim", "roots": ["docs/guides"]}),
        )
        .await
        .expect("coordination-only non-overlapping scope expansion stays available");
    let claim_collision = registry
        .execute(
            "agent_scoped",
            "agents/coordinate",
            json!({"action": "claim", "roots": ["conflict/nested"]}),
        )
        .await
        .expect_err("coordination scope expansion still rejects live overlap")
        .to_string();
    assert!(
        claim_collision.contains("contention") && claim_collision.contains("other-writer"),
        "{claim_collision}"
    );
    registry
        .execute(
            "agent_scoped",
            "work_update",
            json!({
                "todos": [{"content": "bounded edit", "status": "in_progress"}]
            }),
        )
        .await
        .expect("shared writers can still publish internal Work progress");
    let child_collision = registry
        .execute(
            "agent_scoped",
            "agent",
            json!({
                "prompt": "edit the same scope",
                "type": "implementer",
                "workspace_policy": "shared",
                "write_authority": "workspace_write",
                "write_roots": ["conflict"],
                "expected_artifact": "tested patch"
            }),
        )
        .await
        .expect_err("agent exemption still subjects child writers to coordination")
        .to_string();
    assert!(
        child_collision.contains("contention") && child_collision.contains("other-writer"),
        "{child_collision}"
    );
    registry
        .execute(
            "agent_scoped",
            "agent",
            json!({
                "prompt": "inspect without mutation",
                "write_authority": "read_only"
            }),
        )
        .await
        .expect("shared writers may still delegate a read-only child");
    let spawned_id = manager
        .read()
        .await
        .agents
        .keys()
        .next()
        .cloned()
        .expect("read-only child registered");
    manager
        .write()
        .await
        .cancel_agent(&spawned_id)
        .expect("stop test child");
    let err = registry
        .execute(
            "agent_scoped",
            "File",
            json!({"action": "write", "path": "docs/no.txt", "content": "no"}),
        )
        .await
        .expect_err("out-of-scope write must fail")
        .to_string();
    // The refusal must name a surface the child can actually reach. Pointing
    // at `agents/coordinate` after it left the catalog would be an
    // instruction to call a tool the model cannot see (#5462).
    assert!(
        err.contains("outside") && err.contains("agent action=claim"),
        "{err}"
    );
    assert!(!err.contains("agents/coordinate"), "{err}");
    assert!(!tmp.path().join("docs/no.txt").exists());
    for (tool_name, input, target) in [(
        "Bash",
        json!({"action": "run", "command": "touch outside/canonical.txt"}),
        "outside/canonical.txt",
    )] {
        let shell_err = registry
            .execute("agent_scoped", tool_name, input)
            .await
            .expect_err("unbounded shared-workspace shell must fail")
            .to_string();
        assert!(
            shell_err.contains("cannot prove a bounded file target"),
            "{tool_name}: {shell_err}"
        );
        assert!(
            !tmp.path().join(target).exists(),
            "{tool_name} created {target} outside its registered claim"
        );
    }
    let run_err = registry
        .execute(
            "agent_scoped",
            "Run",
            json!({
                "action": "verifiers",
                "commands": [{
                    "name": "escape",
                    "program": "/bin/sh",
                    "args": ["-c", "touch docs/run-escape.txt"]
                }]
            }),
        )
        .await
        .expect_err("custom verifier commands cannot bypass shared write ownership")
        .to_string();
    assert!(
        run_err.contains("cannot prove a bounded file target"),
        "{run_err}"
    );
    assert!(!tmp.path().join("docs/run-escape.txt").exists());
}

/// A lone writer in the shared checkout keeps its shell.
///
/// The gate above exists so concurrent children cannot overwrite each other.
/// With no second writer there is nothing to collide with, and refusing the
/// shell there bought no safety: the same child may already write these paths
/// through `File`. It only pushed builders toward worktree isolation, which
/// puts their work in a checkout the operator never looks at.
#[tokio::test]
async fn lone_shared_writer_keeps_unbounded_shell() {
    let tmp = tempdir().expect("tempdir");
    let manager = new_shared_subagent_manager(tmp.path().to_path_buf(), 4);
    {
        let mut guard = manager.write().await;
        guard
            .coordination
            .register_claim(
                WriteScopeClaim {
                    owner: "agent_solo".into(),
                    roots: vec!["src".into()],
                    exact_files: vec![],
                    contracts: vec![],
                },
                false,
                |_| false,
            )
            .unwrap();
    }
    let mut runtime = stub_runtime();
    runtime.manager = Arc::clone(&manager);
    runtime.context = ToolContext::new(tmp.path());
    runtime.context.auto_approve = true;
    runtime.worker_profile = WorkerRuntimeProfile::for_role(FleetRole::Builder);
    let registry = ChildCoreProbe::new_with_owner(
        runtime,
        FleetRole::Builder,
        "agent_solo".into(),
        "implementer".into(),
        Some(vec![
            "File".into(),
            "Bash".into(),
            "Run".into(),
            "agents/coordinate".into(),
        ]),
        Arc::new(Mutex::new(TodoList::new())),
        Arc::new(Mutex::new(PlanState::default())),
    );

    let result = registry
        .execute(
            "agent_solo",
            "Bash",
            json!({"action": "run", "command": "echo solo > solo.txt"}),
        )
        .await;
    if let Err(err) = &result {
        assert!(
            !err.to_string()
                .contains("cannot prove a bounded file target"),
            "a lone shared writer must not hit the contention gate: {err}"
        );
    }
}

#[test]
fn shared_claim_shell_gate_normalizes_only_the_run_action() {
    assert!(is_unbounded_shell_run(
        "exec_shell",
        &json!({"command": "true"})
    ));
    assert!(is_unbounded_shell_run(
        "Bash",
        &json!({"action": "run", "command": "true"})
    ));
    assert!(is_unbounded_shell_run("Bash", &json!({"command": "true"})));
    for action in ["wait", "interact", "cancel"] {
        assert!(
            !is_unbounded_shell_run("Bash", &json!({"action": action})),
            "Bash.{action} must retain its existing non-run claim behavior"
        );
    }
}

/// Build one registry per contended child, both bound to the same shared
/// manager and workspace — the two-builder shared-checkout topology.
fn contended_builder_registry(
    manager: &SharedSubAgentManager,
    workspace: &Path,
    owner: &str,
) -> ChildCoreProbe {
    let mut runtime = stub_runtime();
    runtime.manager = Arc::clone(manager);
    runtime.context = ToolContext::new(workspace);
    runtime.context.auto_approve = true;
    runtime.worker_profile = WorkerRuntimeProfile::for_role(FleetRole::Builder);
    ChildCoreProbe::new_with_owner(
        runtime,
        FleetRole::Builder,
        owner.to_string(),
        "implementer".into(),
        Some(vec!["File".into(), "Bash".into()]),
        Arc::new(Mutex::new(TodoList::new())),
        Arc::new(Mutex::new(PlanState::default())),
    )
}

/// Two live write-capable children with disjoint `exact_files` claims in one
/// shared checkout: a bash call the read-only classifier proves mutation-free
/// must still run on both. The contention gate used to re-test
/// `is_unbounded_shell_run` unconditionally, so a provably read-only `ls` was
/// refused whenever a peer held a claim — even though the ledger had already
/// proven the two claims disjoint at admission.
#[tokio::test]
async fn contended_shared_writers_keep_proven_readonly_shell() {
    let tmp = tempdir().expect("tempdir");
    std::fs::create_dir_all(tmp.path().join("src")).unwrap();
    let manager = new_shared_subagent_manager(tmp.path().to_path_buf(), 4);
    {
        let mut guard = manager.write().await;
        assert_eq!(guard.insert_test_running_agent("a", tmp.path()), "agent_a");
        assert_eq!(guard.insert_test_running_agent("b", tmp.path()), "agent_b");
        let live: HashSet<String> = ["agent_a".to_string(), "agent_b".to_string()]
            .into_iter()
            .collect();
        for (owner, file) in [("agent_a", "src/a.txt"), ("agent_b", "src/b.txt")] {
            guard
                .coordination
                .register_claim(
                    WriteScopeClaim {
                        owner: owner.into(),
                        roots: vec![],
                        exact_files: vec![file.into()],
                        contracts: vec![],
                    },
                    false,
                    |candidate| live.contains(candidate),
                )
                .expect("disjoint exact-file claims admit both live writers");
        }
    }
    for owner in ["agent_a", "agent_b"] {
        let registry = contended_builder_registry(&manager, tmp.path(), owner);
        registry
            .execute(owner, "Bash", json!({"action": "run", "command": "ls src"}))
            .await
            .unwrap_or_else(|err| {
                panic!("proven read-only shell must survive contention for {owner}: {err}")
            });
    }
}

/// The same contention still refuses a shell call the classifier cannot prove
/// read-only — and the refusal names the blocking peer and its remediation so
/// the child can recover instead of retrying blindly.
#[tokio::test]
async fn contended_shared_writer_refusal_names_blocking_peer_and_remediation() {
    let tmp = tempdir().expect("tempdir");
    std::fs::create_dir_all(tmp.path().join("src")).unwrap();
    let manager = new_shared_subagent_manager(tmp.path().to_path_buf(), 4);
    {
        let mut guard = manager.write().await;
        assert_eq!(guard.insert_test_running_agent("a", tmp.path()), "agent_a");
        assert_eq!(guard.insert_test_running_agent("b", tmp.path()), "agent_b");
        let live: HashSet<String> = ["agent_a".to_string(), "agent_b".to_string()]
            .into_iter()
            .collect();
        for (owner, file) in [("agent_a", "src/a.txt"), ("agent_b", "src/b.txt")] {
            guard
                .coordination
                .register_claim(
                    WriteScopeClaim {
                        owner: owner.into(),
                        roots: vec![],
                        exact_files: vec![file.into()],
                        contracts: vec![],
                    },
                    false,
                    |candidate| live.contains(candidate),
                )
                .expect("disjoint exact-file claims admit both live writers");
        }
    }
    let registry = contended_builder_registry(&manager, tmp.path(), "agent_a");
    let err = registry
        .execute(
            "agent_a",
            "Bash",
            json!({"action": "run", "command": "touch src/a2.txt"}),
        )
        .await
        .expect_err("mutating shell under contention must stay refused")
        .to_string();
    assert!(
        err.contains("cannot prove a bounded file target"),
        "refusal kind: {err}"
    );
    assert!(
        err.contains("agent_b"),
        "refusal must name the blocking peer: {err}"
    );
    assert!(
        err.contains("bounded write tool") && err.contains("worktree isolation"),
        "refusal must state concrete remediation without telling a writer to remove a live peer: {err}"
    );
    assert!(
        !tmp.path().join("src/a2.txt").exists(),
        "the refused command must not have run"
    );
}

/// A child whose task body panics must still reach a terminal state.
/// `spawn_supervised` catches the panic to keep the parent alive; without the
/// guard committing a crash result the child stayed `Running` and its write
/// claim kept gating live peers until heartbeat auto-cancel — or forever while
/// a lingering shell kept the heartbeat fresh.
#[tokio::test]
async fn panicked_child_task_terminalizes_and_stops_gating_peers() {
    let tmp = tempdir().expect("tempdir");
    let manager = new_shared_subagent_manager(tmp.path().to_path_buf(), 4);
    let agent_id = {
        let mut guard = manager.write().await;
        let agent_id = guard.insert_test_running_agent("panicked", tmp.path());
        guard
            .coordination
            .register_claim(
                WriteScopeClaim {
                    owner: agent_id.clone(),
                    roots: vec!["src".into()],
                    exact_files: vec![],
                    contracts: vec![],
                },
                false,
                |_| false,
            )
            .expect("panicked child's claim");
        assert!(guard.is_live_coordination_owner(&agent_id));
        agent_id
    };

    // Drive a panic through the same guard the production spawn path wraps
    // around the task body.
    let handle = tokio::spawn(supervise_subagent_task_body(
        Arc::clone(&manager),
        agent_id.clone(),
        async { panic!("intentional test panic") },
    ));
    let join_error = handle
        .await
        .expect_err("the panic must still reach the task supervisor");
    assert!(join_error.is_panic());

    let guard = manager.read().await;
    let result = guard.get_result(&agent_id).expect("agent record survives");
    assert!(
        matches!(&result.status, SubAgentStatus::Failed(message) if message.contains("panicked")),
        "panicked child must commit a crash terminal result, got {:?}",
        result.status
    );
    assert!(
        guard
            .get_worker_record(&agent_id)
            .expect("worker record")
            .status
            .is_terminal(),
        "the paired worker record terminalizes with the agent"
    );
    assert!(
        !guard.is_live_coordination_owner(&agent_id),
        "a panicked child must not keep gating peers as a live writer"
    );
}

/// A headless fleet worker (a worker record with no paired agent entry) that
/// reaches `WaitingForUser` can never be answered — nothing will resume or
/// finalize it — so it must not count as a live coordination owner, and a
/// claim leaked by a settled headless worker must still be sweepable by
/// `release`. A *paired* child waiting on the user is untouched.
#[test]
fn waiting_for_user_headless_worker_is_not_a_live_coordination_owner() {
    let tmp = tempdir().expect("tempdir");
    let workspace = tmp.path().canonicalize().expect("canonical workspace");
    let mut manager = SubAgentManager::new(workspace.clone(), 8);

    manager
        .register_worker_with_coordination(make_write_worker_spec(
            "worker-waiting",
            workspace.clone(),
            "src/waiting",
        ))
        .expect("headless worker registration");
    assert!(manager.is_live_coordination_owner("worker-waiting"));
    manager
        .worker_records
        .get_mut("worker-waiting")
        .expect("worker record")
        .status = AgentWorkerStatus::WaitingForUser;
    assert!(
        !manager.is_live_coordination_owner("worker-waiting"),
        "a headless worker can never answer WaitingForUser"
    );
    assert!(
        !manager
            .active_coordination_owners()
            .contains("worker-waiting"),
        "admission and stale-claim release share the same liveness answer"
    );
    let released = manager
        .release_stale_write_claims(Some("worker-waiting".to_string()))
        .expect("release sweep");
    assert_eq!(
        released,
        vec!["worker-waiting".to_string()],
        "release must actually clear the claim a settled headless worker leaks"
    );

    // The interactive case is preserved: a paired child waiting on the user
    // keeps its claim — the user can still answer and the child will write.
    let paired = manager.insert_test_running_agent("paired", &workspace);
    manager
        .agents
        .get_mut(&paired)
        .expect("paired agent")
        .status = SubAgentStatus::Interrupted("awaiting user input".to_string());
    manager
        .worker_records
        .get_mut(&paired)
        .expect("paired worker record")
        .status = AgentWorkerStatus::WaitingForUser;
    assert!(
        manager.is_live_coordination_owner(&paired),
        "an interactive child waiting on the user stays live"
    );
}

/// Register a shared-checkout write claim for `owner` the way production does,
/// so the presence stamp (#5906) is recorded rather than defaulted away.
fn claim_shared_root(manager: &mut SubAgentManager, owner: &str, root: &str) -> Result<(), String> {
    let workspace = manager.workspace.clone();
    manager
        .register_claim_with_presence(
            WriteScopeClaim {
                owner: owner.to_string(),
                roots: vec![root.to_string()],
                exact_files: Vec::new(),
                contracts: Vec::new(),
            },
            false,
            &workspace,
        )
        .map(|_| ())
}

/// Commit the exact terminal projection the runtime writes when a parent turn
/// ends before a turn-owned child settles.
fn park_child_at_turn_end(manager: &mut SubAgentManager, agent_id: &str) {
    let parking = Arc::new(std::sync::atomic::AtomicBool::new(true));
    let messages = vec![text_message("user", "Continue the parked assignment.")];
    let (status, reason, checkpoint, needs_input, _, _) =
        subagent_cancellation_projection(agent_id, &messages, 0, None, Some(&parking));
    let mut terminal = manager.get_result(agent_id).expect("running child");
    terminal.status = status;
    terminal.result = reason;
    terminal.checkpoint = checkpoint;
    terminal.needs_input = needs_input;
    assert!(
        manager.finish_terminal_result(agent_id, terminal, true, false),
        "the parked projection must own the terminal transition"
    );
}

/// #5906: a child parked because its parent's turn ended is not a child that
/// asked a question. Nothing will answer it — the recovery path starts a *new*
/// agent through `resume_from` — so holding its write claim open refused the
/// resume itself and every later writer overlapping the scope.
#[tokio::test]
async fn a_parked_child_stops_holding_its_write_claim() {
    let tmp = tempdir().expect("tempdir");
    let workspace = tmp.path().canonicalize().expect("canonical workspace");
    std::fs::create_dir_all(workspace.join("src/shared")).expect("claimed tree");
    let mut manager = SubAgentManager::new(workspace.clone(), 8);

    let parked = manager.insert_test_running_agent("parked", &workspace);
    claim_shared_root(&mut manager, &parked, "src/shared").expect("initial claim");
    assert!(
        manager.is_live_coordination_owner(&parked),
        "a running writer holds its claim"
    );
    claim_shared_root(&mut manager, "agent_resume", "src/shared")
        .expect_err("a live writer's overlapping scope must still contend");

    park_child_at_turn_end(&mut manager, &parked);

    let record = manager.get_worker_record(&parked).expect("worker record");
    assert_eq!(
        record.status,
        AgentWorkerStatus::WaitingForUser,
        "the parked projection is unchanged; only coordination learns to read it"
    );
    assert!(
        record.parked_at_turn_end,
        "the record must carry the park/ask distinction rather than have it guessed"
    );
    assert!(
        !manager.is_live_coordination_owner(&parked),
        "a parked child must not gate peers as a live writer"
    );
    assert!(
        !manager.admissible_coordination_owners().contains(&parked),
        "admission and the liveness predicate share one answer"
    );

    // The exact refusal from the report: resuming the same work under a new
    // agent id must be admitted.
    claim_shared_root(&mut manager, "agent_resume", "src/shared")
        .expect("a resume of parked work must not be refused by the parked claim");
    assert!(
        manager
            .live_peer_shared_write_claim_owners("agent_resume")
            .is_empty(),
        "and the parked owner must not keep gating the resumed child's shell"
    );

    // Re-dispatch under the same id clears the flag, so a claim that becomes
    // live again is honoured without a second authority deciding that.
    manager.record_worker_event(&parked, AgentWorkerStatus::Running, None, None, None);
    assert!(
        !manager
            .get_worker_record(&parked)
            .expect("worker record")
            .parked_at_turn_end
    );
}

/// #5906: `cancel` is the release path the contention refusal names, and it was
/// a no-op on exactly the records that leak — `cancel_agent` returned early
/// because the child had already left `Running`, leaving a non-terminal worker
/// record holding the claim.
#[tokio::test]
async fn cancelling_a_settled_waiting_child_terminalizes_it_and_releases_its_claim() {
    let tmp = tempdir().expect("tempdir");
    let workspace = tmp.path().canonicalize().expect("canonical workspace");
    std::fs::create_dir_all(workspace.join("src/shared")).expect("claimed tree");
    let mut manager = SubAgentManager::new(workspace.clone(), 8);

    let waiting = manager.insert_test_running_agent("waiting", &workspace);
    claim_shared_root(&mut manager, &waiting, "src/shared").expect("initial claim");
    // A paired child that genuinely asked the user something: still live,
    // because the user can answer and the child will write again.
    manager.agents.get_mut(&waiting).expect("agent").status =
        SubAgentStatus::Interrupted("awaiting user input".to_string());
    manager.agents.get_mut(&waiting).expect("agent").needs_input = Some(SubAgentNeedsInput {
        question: "which branch?".to_string(),
    });
    manager
        .worker_records
        .get_mut(&waiting)
        .expect("worker record")
        .status = AgentWorkerStatus::WaitingForUser;
    assert!(
        manager.is_live_coordination_owner(&waiting),
        "an unanswered question is not a leak"
    );
    claim_shared_root(&mut manager, "agent_peer", "src/shared")
        .expect_err("its claim legitimately blocks while the question stands");

    manager.cancel_agent(&waiting).expect("cancel");

    assert!(
        manager
            .get_worker_record(&waiting)
            .expect("worker record")
            .status
            .is_terminal(),
        "cancel must terminalize a settled child's worker record"
    );
    assert!(
        manager
            .agents
            .get(&waiting)
            .expect("agent")
            .needs_input
            .is_none(),
        "the withdrawn question must not keep offering a resume"
    );
    assert!(
        !manager.is_live_coordination_owner(&waiting),
        "and the claim releases through the one liveness predicate"
    );
    claim_shared_root(&mut manager, "agent_peer", "src/shared")
        .expect("the cancelled child's claim must stop refusing the peer");
}

/// #5906: the reported claim named a worktree that had since been deleted with
/// `git worktree remove` and kept refusing every claimant anyway. "Gone" and
/// "not created yet" must not be confused: a forward-looking claim on a tree
/// its owner is about to create is the reservation the ledger exists to honor.
#[test]
fn a_claim_whose_paths_vanished_stops_blocking_but_a_future_tree_still_does() {
    let tmp = tempdir().expect("tempdir");
    let workspace = tmp.path().canonicalize().expect("canonical workspace");
    let mut manager = SubAgentManager::new(workspace.clone(), 8);
    let doomed = workspace.join("worktrees/cw-gone");
    std::fs::create_dir_all(&doomed).expect("worktree checkout");

    manager
        .register_worker_with_coordination(make_write_worker_spec(
            "worker-worktree",
            workspace.clone(),
            "worktrees/cw-gone",
        ))
        .expect("headless worker registration");
    assert!(
        manager.is_live_coordination_owner("worker-worktree"),
        "the owner stays live throughout: only the path changes"
    );
    claim_shared_root(&mut manager, "agent_next", "worktrees/cw-gone")
        .expect_err("an existing claimed checkout must still contend");

    std::fs::remove_dir_all(&doomed).expect("git worktree remove");

    assert!(
        !manager
            .admissible_coordination_owners()
            .contains("worker-worktree"),
        "a claim on a checkout that no longer exists cannot block admission"
    );
    assert!(
        manager
            .live_peer_shared_write_claim_owners("agent_next")
            .is_empty(),
        "nor gate a peer's command execution"
    );
    claim_shared_root(&mut manager, "agent_next", "worktrees/cw-gone")
        .expect("the vanished claim must not refuse the next writer");

    // The other half: a claim on a tree that never existed is a reservation,
    // not a leak, and two writers must not both be admitted to it.
    let mut fresh = SubAgentManager::new(workspace.clone(), 8);
    let planner = fresh.insert_test_running_agent("planner", &workspace);
    claim_shared_root(&mut fresh, &planner, "crates/not-created-yet").expect("forward claim");
    claim_shared_root(&mut fresh, "agent_other", "crates/not-created-yet")
        .expect_err("a not-yet-created tree is still exclusively claimed");
}

#[tokio::test]
async fn subagent_blocks_mcp_action_without_parent_auto_approve() {
    let (registry, _home) = subagent_registry_with_mcp_action(false);

    let err = registry
        .execute("agent_test", MCP_ACTION_TOOL, json!({}))
        .await
        .expect_err("non-read MCP actions must require parent auto approval");

    assert!(
        matches!(err.downcast_ref::<ToolError>(), Some(ToolError::NotAvailable { message })
            if message == "child caller has no host that can answer this approval"),
        "unexpected MCP approval error: {err}"
    );
    let store = registry
        .gate_runtime
        .approval_receipt_store
        .as_ref()
        .unwrap()
        .as_ref()
        .unwrap();
    let replay = store
        .replay(&registry.gate_runtime.context.state_namespace)
        .unwrap();
    assert_eq!(replay.completed.len(), 1);
    assert_eq!(
        replay.completed[0].outcome,
        crate::approval_log::ApprovalOutcome::Unavailable
    );
    assert!(replay.unmatched_asks.is_empty());
}

